cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define BLOCK_SIZE 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int N, int P) {
    // Shared memory for tiles
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    // Thread index within the block
    int thread_row = threadIdx.y;
    int thread_col = threadIdx.x;

    // Block starting index
    int block_row = blockIdx.y * TILE_SIZE;
    int block_col = blockIdx.x * TILE_SIZE;

    // Register accumulation
    float c[BLOCK_SIZE][BLOCK_SIZE] = {{0.0f}};

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        int tiledIndex = t * TILE_SIZE;

        // Load tile from A into shared memory
        int aRow = block_row + thread_row * BLOCK_SIZE;
        int aCol = tiledIndex + thread_col * BLOCK_SIZE;

        for (int i = 0; i < BLOCK_SIZE; i++) {
            for (int j = 0; j < BLOCK_SIZE; j++) {
                int load_row = thread_row * BLOCK_SIZE + i;
                int load_col = thread_col * BLOCK_SIZE + j;

                if (aRow + i < M && aCol + j < N) {
                    As[load_row][load_col] = A[(aRow + i) * N + (aCol + j)];
                } else {
                    As[load_row][load_col] = 0.0f;
                }

                if (tiledIndex + load_row < N && block_col + load_col < P) {
                    Bs[load_row][load_col] = B[(tiledIndex + load_row) * P + (block_col + load_col)];
                } else {
                    Bs[load_row][load_col] = 0.0f;
                }
            }
        }

        __syncthreads();

        // Compute partial sum for this tile using register blocking
        for (int k = 0; k < TILE_SIZE; k++) {
            for (int i = 0; i < BLOCK_SIZE; i++) {
                for (int j = 0; j < BLOCK_SIZE; j++) {
                    c[i][j] += As[thread_row * BLOCK_SIZE + i][k] * Bs[k][thread_col * BLOCK_SIZE + j];
                }
            }
        }

        __syncthreads();
    }

    // Write result to global memory
    for (int i = 0; i < BLOCK_SIZE; i++) {
        for (int j = 0; j < BLOCK_SIZE; j++) {
            int row = block_row + thread_row * BLOCK_SIZE + i;
            int col = block_col + thread_col * BLOCK_SIZE + j;
            if (row < M && col < P) {
                C[row * P + col] = c[i][j];
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Check inputs
    TORCH_CHECK(A.dim() == 2, "A must be 2D");
    TORCH_CHECK(B.dim() == 2, "B must be 2D");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions mismatch");

    int M = A.size(0);
    int N = A.size(1);
    int P = B.size(1);

    auto C = torch::zeros({M, P}, A.options());

    // Calculate grid dimensions
    int gridX = (P + TILE_SIZE - 1) / TILE_SIZE;
    int gridY = (M + TILE_SIZE - 1) / TILE_SIZE;

    // Set grid and block dimensions
    dim3 threadsPerBlock(TILE_SIZE / BLOCK_SIZE, TILE_SIZE / BLOCK_SIZE);
    dim3 numBlocks(gridX, gridY);

    // Launch kernel
    matmul_kernel<<<numBlocks, threadsPerBlock>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, N, P
    );

    return C;
}
"""

