#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int N, int P) {
    // Shared memory for tiles (double buffering)
    __shared__ float As[2][TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[2][TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float sum = 0.0f;
    int stage = 0;

    // Preload first tile
    if (row < M && threadIdx.x < N) {
        As[stage][threadIdx.y][threadIdx.x] = A[row * N + threadIdx.x];
    } else {
        As[stage][threadIdx.y][threadIdx.x] = 0.0f;
    }

    if (threadIdx.y < N && col < P) {
        Bs[stage][threadIdx.y][threadIdx.x] = B[threadIdx.y * P + col];
    } else {
        Bs[stage][threadIdx.y][threadIdx.x] = 0.0f;
    }

    __syncthreads();

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE - 1; t++) {
        // Preload next tile
        int next_stage = stage ^ 1;
        int next_tile = t + 1;

        if (row < M && threadIdx.x + (next_tile * TILE_SIZE) < N) {
            As[next_stage][threadIdx.y][threadIdx.x] = A[row * N + threadIdx.x + (next_tile * TILE_SIZE)];
        } else {
            As[next_stage][threadIdx.y][threadIdx.x] = 0.0f;
        }

        if (threadIdx.y + (next_tile * TILE_SIZE) < N && col < P) {
            Bs[next_stage][threadIdx.y][threadIdx.x] = B[(threadIdx.y + (next_tile * TILE_SIZE)) * P + col];
        } else {
            Bs[next_stage][threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Compute current tile with loop unrolling
        for (int k = 0; k < TILE_SIZE; k += 4) {
            sum += As[stage][threadIdx.y][k] * Bs[stage][k][threadIdx.x];
            sum += As[stage][threadIdx.y][k+1] * Bs[stage][k+1][threadIdx.x];
            sum += As[stage][threadIdx.y][k+2] * Bs[stage][k+2][threadIdx.x];
            sum += As[stage][threadIdx.y][k+3] * Bs[stage][k+3][threadIdx.x];
        }

        __syncthreads();
        stage = next_stage;
    }

    // Compute last tile with loop unrolling
    for (int k = 0; k < TILE_SIZE; k += 4) {
        sum += As[stage][threadIdx.y][k] * Bs[stage][k][threadIdx.x];
        sum += As[stage][threadIdx.y][k+1] * Bs[stage][k+1][threadIdx.x];
        sum += As[stage][threadIdx.y][k+2] * Bs[stage][k+2][threadIdx.x];
        sum += As[stage][threadIdx.y][k+3] * Bs[stage][k+3][threadIdx.x];
    }

    // Write result to global memory
    if (row < M && col < P) {
        C[row * P + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Check inputs
    TORCH_CHECK(A.dim() == 2, "A must be 2D");
    TORCH_CHECK(B.dim() == 2, "B must be 2D");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions mismatch");

    int M = A.size(0);
    int N = A.size(1);
    int P = B.size(1);

    auto C = torch::zeros({M, P}, A.options());

    // Set grid and block dimensions
    dim3 threadsPerBlock(TILE_SIZE, TILE_SIZE);
